  N.add = (N.add || []).concat([{"id": "n95", "n": "위삼(衛三)", "g": "암야전", "grade": "무인", "lv": "절정", "map": "noegong", "zone": "bj", "role": "암야전 서원 '정'의 계율 선생", "memo": "글을 먼저 가르치고 칼을 나중에 가르친다. 🔒 천우록 뒷장에 창랑구첩도 아홉 형이 있다. 노항과 겨루면 원말의 '남은 판'이다(원말 사극 상세 6-2). 암야전 안에서 '칼 없는 자는 베지 않는다'를 고집해 전주 초열과 부딪친다. 천우산화의 반쪽을 쓴다. 🔒 원말 협왕 위소천의 증손. 천우록의 마지막 장(1465년 검은 비가 적혀 있다)을 갖고 있다. 의살 갈래를 되살리려 한다(장삼봉과 원말 사극)."}, {"id": "n96", "n": "노항(盧航)", "g": "장강수로채", "grade": "무인", "lv": "절정", "map": "suzhou", "zone": "th", "role": "장강 동쪽 채주. 태호를 근거로 소금배를 지킨다", "memo": "누가 비무를 걸어도 다 받는다. 창랑구첩도의 반쪽을 쓴다. 🔒 집안 궤짝에 협왕신기 한 장이 있다(뜻을 모른다). 위삼과 겨루면 원말의 '남은 판'이다(원말 사극 상세 6-2). 태호 바닥의 창랑호에서 키(창랑타)를 건져 올리는 것이 집안의 숙원. 🔒 원말 창랑왕 노해천의 방계 후손. 노해천의 시신이 배에 없다는 것을 안다(장삼봉과 원말 사극)."}, {"id": "n97", "n": "곽유(郭維)", "g": "금의위/동창", "grade": "무인", "lv": "일류", "map": "beijing", "zone": "jo", "role": "북진무사 조옥의 늙은 장부지기", "memo": "영락 연간의 '장삼봉 수색 장부'를 지킨다. 수색이 끝나지 않았다고 믿는다. 장부의 마지막 줄은 '천주봉 금전, 접힌 그림'. 🔒 그 줄을 쓴 금의위 천호가 그의 할아버지다. 할아버지는 그 그림을 펼쳐 보려다 상단전이 터졌다(장삼봉과 원말 사극)."}, {"id": "n98", "n": "팽노(彭老)", "g": "하북팽가", "grade": "무인", "lv": "절정", "map": "jinjeong", "zone": "nw", "role": "팽가 사당지기 노인", "memo": "사당의 칼들을 닦는다. 호노(팽호)의 칼도 그가 닦는다. 🔒 사당 뒤에 원말 무적여가의 '무적' 현판이 숨겨져 있다. 대도 성문을 부순 것은 팽가 선조가 아니라 뇌제 여파산이라는 것을 아는 마지막 사람. 병마령 뇌시가 하북에 나타나면 현판을 들고 나간다(장삼봉과 원말 사극)."}, {"id": "n99", "n": "손노파(孫老婆)", "g": "장강수로채", "grade": "무인", "lv": "일류", "map": "suzhou", "zone": "cl", "role": "태호 서산 창랑촌 촌장", "memo": "그물을 기우며 마을 일을 다 안다. 마을 노인들이 하나같이 고수다. '여기는 아무도 못 건드린다'는 원말 손척의 말을 백 년째 지킨다. 🔒 원말 창랑회 우타수 손척의 증손녀. 마을 우물 아래 창랑회의 마지막 금괴가 있다(원말 사극 상세 2)."}, {"id": "n100", "n": "아르슬", "g": "낭인", "grade": "무인", "lv": "절정", "map": "r-hase", "zone": "kz", "role": "명사산 아래 사막 객잔 주인", "memo": "휜 칼을 쓴다. 술값이 과하게 들어오면 '언젠가 칼로 삯을 치르겠다'고 한다. 손님에게 칼을 가르치면 혹독하다. 🔒 원말 무적여가의 만년 3인자 아르슬란의 4대손. 막북에 가지 않은 집이다. 뇌시 여파산이 나타났다는 소식을 들으면 칼을 들고 동쪽으로 간다(원말 사극 상세 5)."}, {"id": "n101", "n": "풍소(風小)", "g": "낭인", "grade": "무인", "lv": "일류", "map": "r-namjikrye", "zone": "fy", "role": "봉양 황각사 터를 쓰는 떠돌이 중", "memo": "빗자루로 절 마당을 쓸며 황각장을 쓴다. 손님이 오면 뒤통수부터 친다. 🔒 홍무 초대 검교장 풍승의 마지막 제자의 손자. 어린 주원장의 이빨 자국이 난 황각사 목어를 숨기고 있다. 동창과 번왕부가 그것을 찾는다(원말에서 명까지 2)."}, {"id": "n102", "n": "연산노기(燕山老騎)", "g": "군마녹림", "grade": "무인", "lv": "절정", "map": "r-hase", "zone": "sd", "role": "감주위의 늙은 기마 교두", "memo": "말 위에서 연산창을 가르친다. 제강천이 군문에 있을 때 그의 스승이었다. 제강천은 그를 '선생'이라고만 부른다. 🔒 할아버지가 연산채 기병이었다. 1449년 토목보 뒤 연산채가 오이라트에 붙던 날을 들어 안다. 그 일로 군마녹림과 북원 사이에 오래된 빚이 있다(원말에서 명까지 5·6)."}, {"id": "n103", "n": "무명(無名)", "g": "낭인", "grade": "무인", "lv": "화경", "map": "r-fujian", "zone": "ns", "role": "남소림 터에 사는 손가락 일곱 없는 노승", "memo": "혈림(남소림 외원)의 마지막 칼. 말을 끊어 묵언 중이다. 단지장·역계수·해맥지를 쓴다. 계율원 사람이 오면 벤다. 🔒 1447년 불 속에서 행자 범허를 밖으로 밀어낸 것이 그다. 1449년 토목보에서 왕진을 친 철퇴 옆에 그가 있었다. 해맥도 하권이 어디 묻혔는지 안다. 범허에게 빚을 받으러 가지 않는다(명대 — 혈림 1-6, 3-2)."}, {"id": "n104", "n": "원진(圓眞)", "g": "소림사", "grade": "무인", "lv": "화경", "map": "sungsan", "zone": "yj", "role": "원진암의 파문승. 옛 계율원 수좌", "memo": "1450년 승병 삼백을 이끌고 북경 성벽에 섰다. 돌아와 파문을 자청했다. 손가락 모자란 노승 몇과 밭을 맨다. 원각의 사조. 🔒 승병 가운데 서른이 남소림 회승이었다. 그는 회승들에게서 세마를 배워 제자에게 넘겼다. 원각이 그것을 끝까지 비틀었다는 것을 알고 자기를 탓한다. 원각을 멈출 수 있는 마지막 사람이다(명대 — 혈림 1-7)."}, {"id": "n105", "n": "사홍(史紅)", "g": "적심회", "grade": "무인", "lv": "절정", "map": "nanjing", "zone": "", "role": "남경 비단 거리의 늙은 염색장이. 적심회 단주", "memo": "손톱 밑이 늘 붉다. 정난 때 죽은 건문 신하의 증손녀. 적갑사를 비단 창고에 숨긴다. '건문 복위'를 말한다. 🔒 바라는 것은 주씨의 끝. 적심 혈조는 가짜다. 지금 황손을 찾는데, 세우려는 것이 아니라 죽이려는 것이다. 황제를 죽인 것이 동창이라는 것을 모른다. 척살록의 '황손' 줄을 적심회가 적었다고 믿지만 아니다(명대 — 적심회 2)."}, {"id": "n106", "n": "하문(何聞)", "g": "금의위/동창", "grade": "", "lv": "이류", "map": "beijing", "zone": "dc", "role": "동창 서고의 늙은 환관. 무적부 잔권을 지킨다", "memo": "왕진 밑에서 무적사 붓을 잡았다. 천순제가 서고를 태울 때 한 권을 품에 넣고 나왔다. 늙은 강호인의 이름을 대면 그의 젊은 날을 줄줄 읊는다. 🔒 잔권을 쓰는 값은 비싸다. 그가 바라는 것은 왕진의 무덤에 술 한 잔 놓아 주는 사람이다(명대 — 3-1, 3-4)."}, {"id": "n107", "n": "정란(程蘭)", "g": "낭인", "grade": "무인", "lv": "일류", "map": "r-fujian", "zone": "qz", "role": "천주 항구의 여검객. 정응의 외손녀", "memo": "할아버지 정응이 어디서 어떻게 죽었는지 찾는다. 식파일격의 첫 형만 안다. 남소림 터로 가는 길을 묻고 다닌다. 🔒 정응이 '찾고도 말하지 않은' 까닭을 알게 되면 그녀도 말하지 않는다. 장부 방의 글씨가 건문의 것임을 알아볼 수 있는 유일한 NPC(집안에 건문의 옛 글씨가 있다)."}, {"id": "n108", "n": "상선(賞善)", "g": "협객도", "grade": "두목", "lv": "현경", "map": "r-guangdong", "zone": "xk", "role": "협객도의 청의 노인. 구리 패에 '상'을 새긴다", "memo": "웃는 얼굴. 손님을 영빈관에 묵게 하고 술을 낸다. 🔒 1265년 태현경 석벽을 푼 한정의 제자. 섬에 버려진 아이였다. 스승이 양양에서 돌아오지 않자 서른 해에 한 번 패를 보내 스승만 한 사람을 찾는다. 의천검 속 한정의 무학을 익힌 자를 알아본다(송말원초 7)."}, {"id": "n109", "n": "벌악(罰惡)", "g": "협객도", "grade": "두목", "lv": "현경", "map": "r-guangdong", "zone": "xk", "role": "협객도의 백의 노인. 구리 패에 '벌'을 새긴다", "memo": "말이 없다. 섬에 온 자의 지난 일을 하나씩 묻는다. 🔒 상선과 함께 한정의 제자. 스승의 마지막 말 '나라가 아니라 사람을 지켜라'를 지킨다. 천마를 끝낼 자를 찾는다. 마계 밖 바다 위라 입마하지 않았다(송말원초 7)."}, {"id": "n110", "n": "임아(林娥)", "g": "활묘", "grade": "무인", "lv": "절정", "map": "seoan", "zone": "hm", "role": "활묘를 지키는 마지막 여인. 무덤 밖에 나간 적이 없다", "memo": "쉰 넘은 나이인데 얼굴이 서른 같다. 현빙상 곁에서 옥봉을 기른다. 활묘심법·군숙합벽(반쪽)을 안다. 정중한 손님에게는 쉴 자리를 준다. 🔒 임씨 여협이 베낀 천장무경 잔장을 지킨다. 종남의 마지막 부부(조군·임숙) 이후 군숙합벽의 짝을 찾지 못했다. 패검종이 쌍검을 쥘 짝을 찾는다는 것을 안다(송말원초 5)."}, {"id": "n111", "n": "노사(老賽)", "g": "상회", "grade": "", "lv": "이류", "map": "r-fujian", "zone": "qz", "role": "천주 항구의 늙은 회회 야장", "memo": "수염이 하얗다. 쇠의 결을 본다. 부러진 신병을 다시 벼린다. 값은 그 칼이 누구를 벴는지 이야기해 주는 것. 🔒 회회 야장 사이프의 후손. 의천검·도룡도를 다시 벼릴 수 있는 유일한 집안. 집에 사이프가 남긴 도첩(현철 녹이는 법)이 있다(송말원초 6-2, 8)."}, {"id": "n112", "n": "바얀(伯顔)", "g": "북원", "grade": "무인", "lv": "절정", "map": "bugwon", "zone": "hl", "role": "화림의 늙은 서고지기. 흠천감 여덟의 후손", "memo": "한문을 몽골 사람보다 잘 읽는다. 칸의 장막 뒤 서고를 지킨다. 🔒 1368년 '칸을 따른 무경'(천장무경)을 지킨다. 북원은 아직 다 읽지 못했다. 그 책에 천마신교 무공의 조문이 있는지 찾는 중이다(송말원초 1-3)."}, {"id": "n113", "n": "우장(牛藏)", "g": "개방", "grade": "", "lv": "이류", "map": "r-shanxi", "zone": "ym", "role": "안문 석각 탁본을 팔러 다니는 늙은 거지", "memo": "안문관 아래 움막에 산다. 탁본 한 장에 술 한 병. 사는 사람은 없다. 개방이 쉬쉬하는 일이라서다. 🔒 철우를 키운 산서 농부 집안의 후손. 집안에 철우의 어릴 적 옷이 있다. 옷 안쪽에 이리 머리 문신과 같은 수가 놓였다(송조 3)."}, {"id": "n114", "n": "공판노인(空盤老人)", "g": "", "grade": "무인", "lv": "화경", "map": "cheonsan", "zone": "hj", "role": "허주궁 터의 눈먼 노인", "memo": "빈 궁 옆 얼음 움막에 산다. 공판기국에 다가오는 자에게 '이기러 왔느냐'고 묻는다. '그렇다'고 하면 돌아가라고 한다. 🔒 1090년대 판을 푼 젊은 승려의 마지막 제자의 제자. 만류귀해공 뒤 반쪽을 외운다. 천마신교가 이 궁 터를 아직 모르는 것은 그가 길을 지워 왔기 때문이다(송조 5)."}, {"id": "n115", "n": "하연(何宴)", "g": "", "grade": "", "lv": "삼류", "map": "gaebong", "zone": "", "role": "개봉의 작은 술집 주인. 연의장 후손", "memo": "낙양 연의장이 무너진 뒤 개봉에 왔다. 가게 뒤 궤짝에 낡은 술사발 서른 개. 팔지 않는다. 🔒 사발 밑에 1083년 철우와 의를 끊은 서른 사람의 이름. 그 가운데 하나가 변장한 모용연이다(송조 3-3, 3-5)."}, {"id": "n116", "n": "모노(慕奴)", "g": "", "grade": "", "lv": "이류", "map": "suzhou", "zone": "th", "role": "태호 섬 빈 장원을 지키는 늙은 하인", "memo": "주인 없는 장원을 쓸고 닦는다. 주인이 언젠가 돌아온다고 믿는다. 🔒 고소 모용가 하인 집안. 장원 서고에 모용가의 옛 장부(천하 무공의 수를 적은 것)가 있다. 패검종 모용단죽이 그 '주인'인 줄은 모른다(송조 3-5)."}]);
  N.memo = (N.memo || []).concat([{"n": "청허진인", "key": "누더기 노인", "add": "🔒 하서에서 그의 곁에 가끔 누더기를 입은 큰 노인이 보인다. 송문고검에 남은 장삼봉의 원영신 조각이다. 무당산 밖이라 오래 버티지 못한다. 송문고검을 무당산 금전에 올리면 온전히 나타난다(장삼봉과 원말 사극 1-8)."}, {"n": "위삼(衛三)", "key": "남은 판", "add": "🔒 천우록 뒷장에 창랑구첩도 아홉 형이 있다. 노항과 겨루면 원말의 '남은 판'이다(원말 사극 상세 6-2)."}, {"n": "노항(盧航)", "key": "남은 판", "add": "🔒 집안 궤짝에 협왕신기 한 장이 있다(뜻을 모른다). 위삼과 겨루면 원말의 '남은 판'이다(원말 사극 상세 6-2)."}, {"n": "범허", "key": "불 밖으로", "add": "🔒 1447년 남소림이 타던 밤 그를 불 밖으로 밀어낸 것은 손가락 일곱 없는 외원승 무명이다. 범허는 원각이 혈림의 무엇을 이었는지 안다. 그래서 혜명을 달마동에 들여보냈다(명대 — 혈림 1-6, 1-7)."}, {"n": "위충", "key": "의용첩", "add": "🔒 우공 의용첩을 갖고 있다. 금의위 지휘사 첫해에 성벽에 섰던 강호인들의 이름을 조용히 빼 주었다. 그래서 늙은 강호인 가운데 그에게 빚진 자가 많다(명대 — 3-4)."}, {"n": "범허", "key": "장경각", "add": "🔒 장경각 청소승의 말 '무공에는 독이 있다'와 '한 사람이 절예 다섯을 넘게 익히지 않는다'의 뜻을 안다. 원각의 길이 그 정반대라는 것도 안다(송조 4)."}]);
